// entities/vectorindex/common/config.go lines 23-32
const (
	DistanceCosine    = "cosine"
	DistanceDot       = "dot"
	DistanceL2Squared = "l2-squared"
	DistanceManhattan = "manhattan"
	DistanceHamming   = "hamming"

	// Set these defaults if the user leaves them blank
	DefaultVectorCacheMaxObjects = 1e12
	DefaultDistanceMetric        = DistanceCosine
)

// entities/vectorindex/hnsw/config.go lines 85-136 (SetDefaults function)
func (u *UserConfig) SetDefaults() {
	u.MaxConnections = DefaultMaxConnections
	u.EFConstruction = DefaultEFConstruction
	u.CleanupIntervalSeconds = DefaultCleanupIntervalSeconds
	u.VectorCacheMaxObjects = vectorIndexCommon.DefaultVectorCacheMaxObjects
	u.EF = DefaultEF
	u.DynamicEFFactor = DefaultDynamicEFFactor
	u.DynamicEFMax = DefaultDynamicEFMax
	u.DynamicEFMin = DefaultDynamicEFMin
	u.Skip = DefaultSkip
	u.FlatSearchCutoff = DefaultFlatSearchCutoff
	u.Distance = vectorIndexCommon.DefaultDistanceMetric  // <-- DEFAULTS TO COSINE
	...
}

// entities/vectorindex/hnsw/config.go lines 213-217 (parsing)
if err := vectorIndexCommon.OptionalStringFromMap(asMap, "distance", func(v string) {
	uc.Distance = v  // <-- ACCEPTS ANY STRING, INCLUDING null
}); err != nil {
	return uc, err
}

// entities/vectorindex/hnsw/config.go lines 260-323 (validate function)
func (u *UserConfig) validate() error {
	var errMsgs []string
	if u.MaxConnections < MinmumMaxConnections {  // <-- validates maxConnections
		errMsgs = append(errMsgs, fmt.Sprintf(
			"maxConnections must be a positive integer with a minimum of %d",
			MinmumMaxConnections,
		))
	}
	if u.EFConstruction < MinmumEFConstruction {  // <-- validates efConstruction
		errMsgs = append(errMsgs, fmt.Sprintf(
			"efConstruction must be a positive integer with a minimum of %d",
			MinmumMaxConnections,
		))
	}
	if u.FilterStrategy != FilterStrategySweeping && u.FilterStrategy != FilterStrategyAcorn {  // <-- validates filterStrategy
		errMsgs = append(errMsgs, "filterStrategy must be either 'sweeping' or 'acorn'")
	}
	// ... other validations ...
	// NO VALIDATION FOR u.Distance FIELD!
	return nil
}
